package dev.notune.transcribe;
public class FileLifecycleProbe { static class Listener implements FileTranscription.Listener {volatile int results,failures;public void onStatus(String s){} public void onReady(){} public void onPartial(String t){} public void onProgress(long a,long b){}public void onDecodeComplete(){}public void onResult(String t,long a,long b){results++;}public void onFailure(FileTranscriptionContract.Failure f){failures++;}}
public static void main(String[] args)throws Exception {Listener l=new Listener(); FileTranscription f=new FileTranscription(new android.content.Context(),null,false,l);f.start();long until=System.nanoTime()+2000000000L;while(l.results==0&&l.failures==0&&System.nanoTime()<until)Thread.sleep(5);if(l.results!=1||l.failures!=0||FileTranscription.released!=1)throw new AssertionError("synchronous Ready lost/failed or handle leaked");FileTranscription.cancelInCreate=true;FileTranscription.released=0;l=new Listener();f=new FileTranscription(new android.content.Context(),null,false,l);f.start();Thread.sleep(25);if(l.results!=0||l.failures!=0||FileTranscription.released!=1)throw new AssertionError("cancel during nativeCreate leaks or delivers");System.out.println("PASS actual Java lifecycle with mocked native/Android boundary: Ready before nativeCreate return and cancel-before-handle handoff");}}
